from playwright.sync_api import sync_playwright
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);page=b.new_page();page.goto('http://127.0.0.1:8000/');results=page.evaluate('''async()=>{const {answerStripSVG}=await import('./cbse-mcq-print.js');const {bubblePoint,scanResponsePhoto,responseGeometry}=await import('./cbse-mcq-scan.js');const results=[];for(const count of [1,10,20]){const geometry=responseGeometry(count,true,true,true),svg=answerStripSVG(count,0,true,true,true,true),img=new Image();img.src='data:image/svg+xml;base64,'+btoa(new XMLSerializer().serializeToString(svg));await img.decode();const strip=document.createElement('canvas');strip.width=geometry.width;strip.height=geometry.height;const g=strip.getContext('2d');g.drawImage(img,0,0);for(let i=0;i<count;i++){const point=bubblePoint(i,i%4);g.fillStyle='black';g.beginPath();g.arc(point.x,point.y,9,0,Math.PI*2);g.fill();}const photo=document.createElement('canvas');photo.width=1100;photo.height=700;const ctx=photo.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,1100,700);ctx.drawImage(strip,180,200,strip.width*.65,strip.height*.65);const found=scanResponsePhoto(photo,count,{compact:true});results.push({count,answers:found.responses.join(''),alignment:found.alignment});}return results;}''');
 for result in results:assert result['answers']==''.join('ABCD'[i%4] for i in range(result['count'])),result
 b.close()
print('PASS tight markers bracket circles for 1/10/20 questions and scan correctly from a smaller answer block inside a larger photo')
